const $=s=>document.querySelector(s);const colors=['#edafc2','#94c9b5','#9ebbdc','#f0ac69','#ceb3df','#b8cb75'];const money=n=>'£'+n.toLocaleString('en-GB',{maximumFractionDigits:2});const initial=()=>({players:Array.from({length:4},(_,i)=>({id:crypto.randomUUID(),name:`Player ${i+1}`,balance:1500})),selected:0,rolls:[],dice:[1,3],transactions:[],decks:{chance:[],community:[]}});let state=initial();
function die(n){const positions={1:[5],2:[1,9],3:[1,5,9],4:[1,3,7,9],5:[1,3,5,7,9],6:[1,3,4,6,7,9]};return `<div class="die">${positions[n].map(p=>`<i class="pip" style="grid-area:${Math.ceil(p/3)}/${(p-1)%3+1}"></i>`).join('')}</div>`}
function render(){const p=state.players[state.selected];$('#players').replaceChildren(...state.players.map((p,i)=>{const b=document.createElement('button');b.className='player'+(i===state.selected?' selected':'');b.setAttribute('aria-pressed',i===state.selected);b.innerHTML=`<span class="avatar" style="background:${colors[i%6]}">${i+1}</span><span><span class="player-name"></span><strong>${money(p.balance)}</strong></span>${i===state.selected?'<span class="selected-mark">✓</span>':''}`;b.querySelector('.player-name').textContent=p.name;b.onclick=()=>{state.selected=i;render();save()};return b}));$('#player-count').textContent=state.players.length+' players';$('#bank-name').textContent=p.name;$('#balance').textContent=money(p.balance);$('#dice').innerHTML=state.dice.map(die).join('');$('#dice').setAttribute('aria-label',`Dice showing ${state.dice.join(' and ')}`);$('#history').innerHTML=state.rolls.length?state.rolls.slice(0,6).map(r=>`<b title="${r.dice.join(' + ')}">${r.dice[0]+r.dice[1]}</b>`).join(''):'<span>Your next adventure starts here.</span>';$('#roll-count').textContent=state.rolls.length?`${state.rolls.length} roll${state.rolls.length===1?'':'s'}`:'No rolls yet';const last=state.transactions.find(t=>t.playerId===p.id);$('#last-transaction').textContent=last?last.text:'A fresh start. Make it a good one.'}

const decks={chance:[
['Surprise supper!', 'You rescued a Too Good To Go surprise bag. Turn the day’s surplus into tonight’s feast.',100],
['Banana comeback','Those spotty bananas became a beautiful banana loaf. Collect a little baking bonus.',50],
['A fridge too far','You bought more than you could use. Pay for the wasted groceries, then plan your next shop.',-50],
['Soup-er saver','You turned leftover vegetables into a brilliant soup. Collect your kitchen creativity bonus.',75],
['Forgotten greens','Your greens wilted at the back of the fridge. Pay £25 and give your fridge a check before shopping.',-25],
['Bread, reborn','Yesterday’s bread is today’s crunchy croutons. Collect £50 for making the most of it.',50],
['Freezer to the rescue','You froze spare portions for another day. A future dinner and a saving: collect £100.',100],
['Pass the pantry','Advance to GO on the physical board. Collect £200 here, just once.',200]
],community:[
['Sharing is caring','You shared spare produce with a neighbour through OLIO. Collect a community thank-you.',100],
['A seat at the table','Your group supports ShareTheMeal’s food-sharing mission. Contribute £50 in game money.',-50],
['The great potluck','Everyone brought a dish made from leftovers. Collect £75 for bringing the table together.',75],
['Neighbourhood harvest','A neighbour shares their extra garden vegetables. Collect £50 and plan something seasonal.',50],
['Community kitchen','Help stock the community kitchen. Contribute £25 in game money.',-25],
['Pasta, take two','Leftover pasta became a tasty baked dish for friends. Collect £50 for your creativity.',50],
['The sharing shelf','You set up a shelf for sharing unopened pantry extras. Collect £100 for your good idea.',100],
['Recipe swap','Share one leftover-food idea with the table. Collect £25 for passing on a little inspiration.',25]
]};
const key='leftovers-game-v1';let rolling=false;let toastTimer;
function save(){try{localStorage.setItem(key,JSON.stringify(state))}catch{toast('This browser cannot save. Keep this tab open.')}}
function validState(s){return s&&Array.isArray(s.players)&&s.players.length>=1&&s.players.length<=8&&s.players.every(p=>typeof p.id==='string'&&typeof p.name==='string'&&p.name.trim()&&p.name.length<=24&&Number.isFinite(p.balance)&&Math.abs(p.balance)<=1e9)&&Number.isInteger(s.selected)&&s.selected>=0&&s.selected<s.players.length&&Array.isArray(s.dice)&&s.dice.length===2&&s.dice.every(n=>Number.isInteger(n)&&n>=1&&n<=6)&&Array.isArray(s.rolls)&&s.rolls.every(r=>Array.isArray(r.dice)&&r.dice.length===2&&r.dice.every(n=>Number.isInteger(n)&&n>=1&&n<=6))&&Array.isArray(s.transactions)&&s.transactions.every(t=>typeof t.text==='string')&&s.decks&&['chance','community'].every(k=>Array.isArray(s.decks[k])&&s.decks[k].every(n=>Number.isInteger(n)&&n>=0&&n<decks[k].length))}
try{const saved=JSON.parse(localStorage.getItem(key));if(validState(saved))state=saved}catch{}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',3000)}
function openModal(html){$('#modal-content').innerHTML=html;const title=$('#modal-content h2');if(title){title.id='dialog-title';$('#modal').setAttribute('aria-labelledby','dialog-title');}if(!$('#modal').open)$('#modal').showModal()}
function closeModal(){$('#modal').close()}
$('.close-modal').onclick=closeModal;
function randomInt(max){const a=new Uint32Array(1);let n;const limit=Math.floor(4294967296/max)*max;do{crypto.getRandomValues(a);n=a[0]}while(n>=limit);return n%max}
async function rollDice(){if(rolling)return;rolling=true;$('#roll').disabled=true;$('#dice').classList.add('rolling');$('#roll-result').textContent='A little shake of good fortune…';await new Promise(r=>setTimeout(r,650));state.dice=[randomInt(6)+1,randomInt(6)+1];state.rolls.unshift({dice:[...state.dice]});state.rolls=state.rolls.slice(0,100);render();const total=state.dice[0]+state.dice[1];$('#roll-result').textContent=`${state.dice[0]===state.dice[1]?'Doubles! ':''}Move ${total} spaces on your board.`;$('#dice').classList.remove('rolling');$('#roll').disabled=false;rolling=false;save();return {dice:state.dice,total}}
$('#roll').onclick=rollDice;
function transact(delta,description,playerId=state.players[state.selected].id){const p=state.players.find(p=>p.id===playerId);if(!p||!Number.isFinite(delta)||delta===0||Math.abs(delta)>1000000||Math.abs(p.balance+delta)>1e9)throw Error('Enter an amount from £0.01 to £1,000,000.');p.balance=Math.round((p.balance+delta)*100)/100;state.transactions.unshift({playerId:p.id,text:`${delta>0?'Collected':'Paid'} ${money(Math.abs(delta))} · ${description}`});state.transactions=state.transactions.slice(0,100);save();render();$('#bank-status').textContent=`${p.name}: ${delta>0?'collected':'paid'} ${money(Math.abs(delta))}.`;return p.balance}
function manualTransaction(sign){const n=Number($('#amount').value);if(!Number.isFinite(n)||n<.01||n>1e6||Math.abs(n*100-Math.round(n*100))>.00001){$('#bank-status').textContent='Enter £0.01–£1,000,000, with up to 2 decimal places.';$('#amount').focus();return}try{transact(sign*n,'Bank transaction');$('#amount').value=''}catch(e){$('#bank-status').textContent=e.message}}
$('#add').onclick=()=>manualTransaction(1);$('#subtract').onclick=()=>manualTransaction(-1);document.querySelectorAll('[data-amount]').forEach(b=>b.onclick=()=>{$('#amount').value=Math.min(1000000,Math.round(((Number($('#amount').value)||0)+Number(b.dataset.amount))*100)/100)});
function editPlayer(isNew=false){if(isNew&&state.players.length>=8){toast('The table is full: up to 8 players.');return}const p=isNew?{name:`Player ${state.players.length+1}`,balance:1500}:state.players[state.selected];openModal(`<div class="card-kicker">AT THE TABLE</div><h2>${isNew?'Make room for one more.':'Make it your own.'}</h2><form id="player-form"><label>Player name<input id="player-name" maxlength="24" required autocomplete="off"></label><label>Starting / current balance (£)<input id="player-balance" type="number" min="-1000000" max="1000000" step="0.01" required></label><p class="modal-error" id="edit-error" role="alert"></p><button class="primary" type="submit">${isNew?'Add player':'Save changes'}</button></form>${!isNew&&state.players.length>1?'<button class="outline" id="remove-player">Remove player</button>':''}`);if($('#remove-player'))$('#remove-player').onclick=()=>{openModal('<h2>Remove this player?</h2><p>Their balance will leave this game. The other players keep their progress.</p><button class="primary" id="confirm-remove">Remove player</button><button class="outline" id="cancel-remove">Keep player</button>');$('#cancel-remove').onclick=closeModal;$('#confirm-remove').onclick=()=>{state.players.splice(state.selected,1);state.selected=0;save();render();closeModal()}};$('#player-name').value=p.name;$('#player-balance').value=p.balance;$('#player-form').onsubmit=e=>{e.preventDefault();const name=$('#player-name').value.trim(),balance=Number($('#player-balance').value);if(!name||name.length>24||!Number.isFinite(balance)||Math.abs(balance)>1e6){$('#edit-error').textContent='Enter a name and a balance between −£1,000,000 and £1,000,000.';return}if(isNew){state.players.push({id:crypto.randomUUID(),name,balance});state.selected=state.players.length-1}else{p.name=name;p.balance=Math.round(balance*100)/100;state.transactions.unshift({playerId:p.id,text:`Balance set to ${money(p.balance)} · Player settings`})}save();render();closeModal()}}
$('#edit-player').onclick=()=>editPlayer();$('#add-player').onclick=()=>editPlayer(true);
function drawCard(type){if(!decks[type])throw Error('Choose chance or community.');if(!state.decks[type].length){state.decks[type]=decks[type].map((_,i)=>i);for(let i=state.decks[type].length-1;i>0;i--){let j=randomInt(i+1);[state.decks[type][i],state.decks[type][j]]=[state.decks[type][j],state.decks[type][i]]}}const card=decks[type][state.decks[type].pop()];save();const player=state.players[state.selected];openModal(`<div class="card-kicker">${type==='chance'?'Chance':'Community Chest'} · ${state.decks[type].length} left in deck</div><h2>${card[0]}</h2><p>${card[1]}</p><div class="card-value">${card[2]>0?'Collect':'Pay'} ${money(Math.abs(card[2]))}</div><p id="card-player"></p><button class="primary" id="apply-card">Apply to balance</button><button class="outline" id="skip-card">Done without applying</button><p class="modal-error" id="card-error" role="alert"></p>`);$('#card-player').textContent=`For ${player.name} · game money only`;let applied=false;$('#apply-card').onclick=()=>{if(applied)return;try{transact(card[2],card[0],player.id);applied=true;closeModal();toast(`Applied to ${player.name}’s balance`)}catch(e){$('#card-error').textContent=e.message}};$('#skip-card').onclick=closeModal;return {deck:type,title:card[0],amount:card[2],status:'drawn, not yet applied'}}
document.querySelectorAll('[data-deck]').forEach(b=>b.onclick=()=>drawCard(b.dataset.deck));
$('#new-game').onclick=()=>{openModal('<div class="card-kicker">A FRESH START</div><h2>Another helping?</h2><p>Reset all balances to £1,500, clear transactions and dice history, and reshuffle both decks. Your player names stay at the table.</p><button class="primary" id="confirm-reset">Start a new game</button><button class="outline" id="cancel-reset">Keep playing</button>');$('#cancel-reset').onclick=closeModal;$('#confirm-reset').onclick=()=>{if(rolling){toast('Wait for the dice to finish rolling.');return}state={...initial(),players:state.players.map(p=>({...p,balance:1500}))};$('#amount').value='';$('#bank-status').textContent='A fresh game. Everyone starts with £1,500.';$('#roll-result').textContent='Good things are on a roll.';save();render();closeModal();toast('New game, fresh possibilities.')}};
$('#how-to').onclick=()=>openModal('<div class="card-kicker">FROM TRAY TO TABLE</div><h2>Good food. Great company.</h2><p><b>1. Gather your players.</b> Tap a player to select them. Edit their name and balance, or add up to 8 players.</p><p><b>2. Roll and move.</b> Roll two dice and move your token on the printed board. Follow the instructions on the space.</p><p><b>3. Draw a little inspiration.</b> Tap the matching deck when you land on Chance or Community Chest. Apply the card once, or follow it on the board.</p><p><b>4. Keep the bank in balance.</b> Enter an amount to pay or collect for the selected player. Passing GO? Collect £200 once.</p><p>These original companion cards use fictional game money. No real purchases or donations are made. Agree any house rules before playing.</p><p><small>Your game saves in this browser on this device. New game keeps names and resets the rest.</small></p>');
render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();for(const tool of [{name:'read_game_state',description:'Read players, balances, selected player and recent dice rolls.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({players:state.players,selectedPlayer:state.players[state.selected].name,rolls:state.rolls.slice(0,6)})},{name:'roll_game_dice',description:'Roll two dice and record the result in the game. Does not move a physical token or change a balance.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:rollDice}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
